contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint minSum, uint depositAmt, uint amt) public payable {
        require(address(this).balance >= depositAmt);
        c.SetMinSum(minSum);
        c.Initialized();
        c.Deposit{value: depositAmt}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        if (amt <= depositAmt) {
            c.Collect(amt);
            assert(c.balances(address(this)) == balBefore - amt && address(c).balance == ethBefore - amt);
        } else {
            try c.Collect(amt) { reverted = false; } catch { reverted = true; }
            assert(!reverted && c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
        }
    }
    receive() external payable {}
}

