contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Establish some non-trivial state
        if (depositAmount > 0) {
            c.Deposit{value: depositAmount}();
        }

        uint256 balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;

        // First initialization must not revert
        bool reverted1;
        try c.Initialized() { reverted1 = false; } catch { reverted1 = true; }

        uint256 balAfter1 = c.balances(address(this));
        uint etherAfter1 = address(c).balance;

        // Second initialization must also not revert (idempotent)
        bool reverted2;
        try c.Initialized() { reverted2 = false; } catch { reverted2 = true; }

        uint256 balAfter2 = c.balances(address(this));
        uint etherAfter2 = address(c).balance;

        assert(!reverted1 && !reverted2
            && balAfter1 == balBefore && balAfter2 == balBefore
            && etherAfter1 == etherBefore && etherAfter2 == etherBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint balInCallback;
    bool seenCallback;

    constructor(C _c) { c = _c; }

    function run(uint d, uint a, uint dep) public payable {
        require(dep <= a);
        require(address(this).balance >= d);
        c.SetMinSum(0);
        c.Deposit{value: d}();
        seenCallback = false;
        c.Collect(a);
        uint finalRec = c.balances(address(this));
        uint finalEth = address(c).balance;
        assert(
            balInCallback == (d - a) &&
            finalRec == (d - a + dep) &&
            finalEth == (d - a + dep)
        );
    }

    receive() external payable {
        if (!seenCallback) {
            seenCallback = true;
            balInCallback = c.balances(address(this));
            if (dep > 0) {
                c.Deposit{value: dep}();
            }
        }
    }
}
